<?php require 'db.php'; $method=$_SERVER['REQUEST_METHOD']; if($method==='GET'){ $st=$pdo->query('SELECT vf.*,f.nombre AS nombre_farmacia FROM visitas_farmacias vf JOIN farmacias f ON f.id_farmacia=vf.id_farmacia ORDER BY vf.fecha DESC'); echo json_encode($st->fetchAll()); exit; } $d=json_decode(file_get_contents('php://input'),true) ?: []; if($method==='POST'){ $st=$pdo->prepare('INSERT INTO visitas_farmacias(id_farmacia,fecha,stock_productos,pedido_sugerido,observaciones) VALUES(?,?,?,?,?)');$st->execute([$d['id_farmacia'],$d['fecha'],$d['stock_productos']??null,$d['pedido_sugerido']??null,$d['observaciones']??null]);echo json_encode(['success'=>true]);exit;} if($method==='DELETE'){ $pdo->prepare('DELETE FROM visitas_farmacias WHERE id_visita_farmacia=?')->execute([$_GET['id']]);echo json_encode(['success'=>true]); }
